package com.telco.sim.controller;

import com.telco.sim.dto.ESimReassignRequest;
import com.telco.sim.model.Subscriber;
import com.telco.sim.repository.SubscriberRepository;
import com.telco.sim.service.ESimProvisioningService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/telecom/api/v2/subscribers")
public class SimManagementController {

    private final SubscriberRepository subscriberRepository;
    private final ESimProvisioningService esimService;

    public SimManagementController(SubscriberRepository subscriberRepository, ESimProvisioningService esimService) {
        this.subscriberRepository = subscriberRepository;
        this.esimService = esimService;
    }

    @PutMapping("/{subscriberId}/esim/reassign")
    public ResponseEntity<String> reassignESimProfile(
            @PathVariable Long subscriberId,
            @Valid @RequestBody ESimReassignRequest request,
            Authentication authentication) {
        Subscriber subscriber = subscriberRepository.findById(subscriberId)
                .orElseThrow(() -> new IllegalArgumentException("Subscriber record not found"));
        if (!subscriber.getAccountUsername().equals(authentication.getName())) {
            throw new AccessDeniedException("Cannot reassign eSIM for a subscriber not owned by the authenticated account");
        }
        esimService.reassignIccid(subscriber, request.getTargetIccid(), request.getDeviceEid());
        return ResponseEntity.ok("eSIM profile reallocated to new ICCID");
    }
}
